@st.cache_data(ttl=300, show_spinner=False)
def fetch_meta_filter_rows(client_id, account_id, api_key):
    headers = {
        "accept": "*/*",
        "content-type": "application/json",
        "x-api-key": api_key,
        "origin": "https://inhaus-marketing-api.web.app",
