                        "adset_name": adset.get("name", ""),
                        "ad_id": ad.get("id", ""),
                        "ad_name": ad.get("name", ""),
                    })
            paging = body.get("paging", {})
            after = (paging.get("cursors") or {}).get("after")
            if not after or not paging.get("next"):
                break
        return rows, None
    except Exception as e:
        return [], f"Error cargando filtros Meta: {e}"


